"""Empirical verification of every structural conclusion of the classification."""
from __future__ import annotations
from typing import List, Set

def greedy(n_terms: int) -> List[int]:
    seq, forbidden = [1], {2}
    for _ in range(1, n_terms):
        z = seq[-1] + 1
        while z in forbidden:
            z += 1
        for x in seq:
            forbidden.add(x + z)
        forbidden.add(2 * z)
        seq.append(z)
    return seq

def verify(N: int = 100) -> dict:
    s = greedy(N)
    return {
        "matches_closed_form": s == [2 * n + 1 for n in range(N)],
        "constant_increment_2": all(s[i+1]-s[i] == 2 for i in range(N-1)),
        "all_odd": all(x % 2 == 1 for x in s),
        "value_set_is_odds": set(s) == {2*n+1 for n in range(N)},
        "distinct_prefixes": all(len(set(s[:m])) == m for m in range(N+1)),
    }

if __name__ == "__main__":
    for k, v in verify().items():
        print(f"{k}: {v}")

