from __future__ import annotations
from typing import List, Set

def greedy_anti_fibonacci(n_terms: int) -> List[int]:
    """Generate the repaired anti-Fibonacci sequence by direct greedy search.

    At each step choose the least z > a[-1] such that z is not the sum of two
    earlier terms.  Returns the first n_terms terms (which equal 2*i+1).
    """
    if n_terms <= 0:
        return []
    seq: List[int] = [1]
    forbidden: Set[int] = {1 + 1}
    for _ in range(1, n_terms):
        z: int = seq[-1] + 1
        while z in forbidden:
            z += 1
        for x in seq:
            forbidden.add(x + z)
        forbidden.add(z + z)
        seq.append(z)
    return seq

