from __future__ import annotations
from typing import List, Set

def is_repaired_prefix(seq: List[int]) -> bool:
    """Certify that a finite prefix obeys the repaired rule at every stage.

    Checks a[0] == 1 and, for each n, that a[n+1] is the LEAST value strictly
    above a[n] avoiding all pair sums a_i + a_j with i, j <= n.  A True result on
    every prefix is exactly the hypothesis of the rigidity theorem, which then
    forces the whole sequence to be a_n = 2n+1.
    """
    if not seq or seq[0] != 1:
        return False
    for n in range(len(seq) - 1):
        history = seq[: n + 1]
        forbidden: Set[int] = {history[i] + history[j]
                               for i in range(len(history))
                               for j in range(len(history))}
        # least admissible value strictly above a[n]
        z = seq[n] + 1
        while z in forbidden:
            z += 1
        if seq[n + 1] != z:
            return False
    return True
